-- Generated by Supabase CLI as 20261004104811; ordered after admin foundations.
-- Data-rights compatibility only. No retention period, purge, cascade or backfill.
BEGIN;

CREATE FUNCTION private.admin_data_rights_owner(p_actor uuid, p_org uuid)
RETURNS void LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.profiles p JOIN auth.users u ON u.id=p.id
   JOIN public.organizations o ON o.id=p.org_id WHERE p.id=p_actor AND p.org_id=p_org
   AND p.role='owner' AND p.access_revoked_at IS NULL) THEN
  RAISE EXCEPTION 'DATA_RIGHTS_FORBIDDEN' USING ERRCODE='42501';
 END IF;
END $$;
REVOKE ALL ON FUNCTION private.admin_data_rights_owner(uuid,uuid) FROM PUBLIC,anon,authenticated,service_role;

CREATE FUNCTION private.admin_public_support_event_values(p_values jsonb)
RETURNS jsonb LANGUAGE sql IMMUTABLE SET search_path='' AS $$
 SELECT COALESCE(jsonb_object_agg(e.key,e.value),'{}') FROM jsonb_each(p_values)e
 WHERE e.key IN('status','priority','category','resolutionCode','nextUpdateDueAt')
 AND jsonb_typeof(e.value) IN('string','null')
$$;
REVOKE ALL ON FUNCTION private.admin_public_support_event_values(jsonb) FROM PUBLIC,anon,authenticated,service_role;

-- Append-only record ordering gives complete cursor traversal without exposing
-- public table internals. Caller identity/org is supplied only by a verified server loader.
CREATE FUNCTION public.admin_requester_support_export(
 p_actor_id uuid,p_org_id uuid,p_as_of timestamptz,p_limit integer DEFAULT 100,p_cursor jsonb DEFAULT NULL
) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE v_result jsonb;v_limit integer:=LEAST(100,GREATEST(1,COALESCE(p_limit,100)));
BEGIN
 IF COALESCE(auth.jwt()->>'role','')<>'service_role' THEN RAISE EXCEPTION 'DATA_RIGHTS_FORBIDDEN' USING ERRCODE='42501';END IF;
 PERFORM private.admin_data_rights_owner(p_actor_id,p_org_id);
 IF p_as_of IS NULL OR p_as_of>clock_timestamp()+interval '5 minutes' THEN RAISE EXCEPTION 'DATA_RIGHTS_INVALID' USING ERRCODE='22023';END IF;
 IF p_cursor IS NOT NULL AND(jsonb_typeof(p_cursor)<>'object' OR(p_cursor->>'rank')::integer NOT BETWEEN 0 AND 2
   OR p_cursor->>'id' IS NULL OR p_cursor->>'createdAt' IS NULL) THEN RAISE EXCEPTION 'DATA_RIGHTS_INVALID' USING ERRCODE='22023';END IF;
 WITH own AS(
  SELECT * FROM public.support_tickets WHERE org_id=p_org_id AND requester_user_id=p_actor_id AND created_at<=p_as_of
 ), records AS(
  SELECT 0 AS rank,t.created_at,t.id,'ticket'::text AS kind,jsonb_build_object(
   'id',t.id,'subject',t.subject,'category',t.category,'priority',t.priority,'status',t.status,'source',t.source,
   'createdAt',t.created_at,'updatedAt',t.updated_at,'nextUpdateDueAt',t.next_update_due_at,'resolvedAt',t.resolved_at,
   'resolutionCode',t.resolution_code,'resolutionSummary',t.resolution_summary)AS value FROM own t
  UNION ALL
  SELECT 1,m.created_at,m.id,'message',jsonb_build_object('id',m.id,'ticketId',m.ticket_id,'authorKind',m.author_kind,
   'messageKind',m.message_kind,'body',m.body,'createdAt',m.created_at,'messageSeq',m.message_seq::text)
   FROM public.support_messages m JOIN own t ON t.id=m.ticket_id WHERE m.created_at<=p_as_of
  UNION ALL
  SELECT 2,e.created_at,e.id,'event',jsonb_build_object('id',e.id,'ticketId',e.ticket_id,'eventType',e.event_type,
   'createdAt',e.created_at,'before',private.admin_public_support_event_values(e.before_safe),'after',private.admin_public_support_event_values(e.after_safe))
   FROM public.support_ticket_events e JOIN own t ON t.id=e.ticket_id WHERE e.public_visible AND e.created_at<=p_as_of
 ), selected AS(
  SELECT * FROM records WHERE p_cursor IS NULL OR(rank,created_at,id)>
   ((p_cursor->>'rank')::integer,(p_cursor->>'createdAt')::timestamptz,(p_cursor->>'id')::uuid)
   ORDER BY rank,created_at,id LIMIT v_limit+1
 ), numbered AS(SELECT *,row_number()OVER(ORDER BY rank,created_at,id)AS n FROM selected)
 SELECT jsonb_build_object('items',COALESCE((SELECT jsonb_agg(jsonb_build_object('kind',kind,'value',value)ORDER BY n)FROM numbered WHERE n<=v_limit),'[]'),
  'nextCursor',CASE WHEN EXISTS(SELECT 1 FROM numbered WHERE n>v_limit) THEN
   (SELECT jsonb_build_object('rank',rank,'createdAt',created_at,'id',id)FROM numbered WHERE n=v_limit)ELSE NULL END)INTO v_result;
 RETURN v_result;
END $$;
REVOKE ALL ON FUNCTION public.admin_requester_support_export(uuid,uuid,timestamptz,integer,jsonb) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.admin_requester_support_export(uuid,uuid,timestamptz,integer,jsonb) TO service_role;

-- Pending policy decisions are fail-closed. Even resolved/unbound tickets and
-- projection metadata require review; this does not delete or relabel them.
CREATE FUNCTION private.admin_account_deletion_needs_review(p_actor uuid,p_org uuid)
RETURNS boolean LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path='' AS $$
DECLARE v_review boolean;
BEGIN
 SELECT EXISTS(SELECT 1 FROM public.support_tickets WHERE org_id=p_org)
 OR EXISTS(SELECT 1 FROM private.admin_org_reporting WHERE org_id=p_org)
 OR EXISTS(SELECT 1 FROM private.admin_billing_facts WHERE org_id=p_org)
 OR EXISTS(SELECT 1 FROM private.support_request_results WHERE actor_key IN
   (SELECT id::text FROM public.profiles WHERE org_id=p_org))
 OR EXISTS(SELECT 1 FROM private.platform_founder_grants WHERE user_id IN
   (SELECT id FROM public.profiles WHERE org_id=p_org) OR created_by IN
   (SELECT id FROM public.profiles WHERE org_id=p_org))
 OR EXISTS(SELECT 1 FROM private.platform_admin_sessions WHERE user_id IN
   (SELECT id FROM public.profiles WHERE org_id=p_org)) INTO v_review;
 IF v_review THEN RETURN true; END IF;
 -- The MFA setup slice is additive and ordered after this migration. A fixed
 -- table/query check protects its restrictive Auth reference once present;
 -- there is no caller-controlled table name or credential material here.
 IF pg_catalog.to_regclass('private.platform_founder_mfa_setup_intents') IS NOT NULL THEN
  EXECUTE 'SELECT EXISTS(SELECT 1 FROM private.platform_founder_mfa_setup_intents WHERE user_id IN (SELECT id FROM public.profiles WHERE org_id=$1))'
   INTO v_review USING p_org;
 END IF;
 RETURN v_review;
END
$$;
REVOKE ALL ON FUNCTION private.admin_account_deletion_needs_review(uuid,uuid) FROM PUBLIC,anon,authenticated,service_role;

CREATE FUNCTION public.admin_account_deletion_preflight(p_actor_id uuid,p_org_id uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE v_review boolean;
BEGIN
 IF COALESCE(auth.jwt()->>'role','')<>'service_role' THEN RAISE EXCEPTION 'DATA_RIGHTS_FORBIDDEN' USING ERRCODE='42501';END IF;
 PERFORM private.admin_data_rights_owner(p_actor_id,p_org_id);
 IF NOT EXISTS(SELECT 1 FROM public.organizations WHERE id=p_org_id AND owner_id=p_actor_id)THEN RAISE EXCEPTION 'DATA_RIGHTS_FORBIDDEN' USING ERRCODE='42501';END IF;
 v_review:=private.admin_account_deletion_needs_review(p_actor_id,p_org_id);
 RETURN jsonb_build_object('allowed',NOT v_review,'reason',CASE WHEN v_review THEN 'review_required' ELSE 'ready' END);
END $$;
REVOKE ALL ON FUNCTION public.admin_account_deletion_preflight(uuid,uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.admin_account_deletion_preflight(uuid,uuid) TO service_role;

-- Preserve the prior tenant deletion behavior behind an owner-bound wrapper.
-- Profile lock order matches the old operation. FOR UPDATE on organizations
-- serializes incoming FK key-share locks; the review check runs after locking,
-- before the old operation can erase any records. No ticket/cascade is added.
ALTER FUNCTION public.delete_account_permanently(text,text) SET SCHEMA private;
ALTER FUNCTION private.delete_account_permanently(text,text) RENAME TO delete_account_pre_admin;
REVOKE ALL ON FUNCTION private.delete_account_pre_admin(text,text) FROM PUBLIC,anon,authenticated,service_role;
CREATE FUNCTION public.delete_account_permanently(p_confirmation_name text,p_confirmation_phrase text)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE v_actor uuid:=auth.uid();v_org uuid;
BEGIN
 SELECT org_id INTO v_org FROM public.profiles WHERE id=v_actor AND role='owner' AND access_revoked_at IS NULL FOR UPDATE;
 IF v_org IS NULL THEN RAISE EXCEPTION 'DATA_RIGHTS_FORBIDDEN' USING ERRCODE='42501';END IF;
 PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(v_org::text,0));
 PERFORM 1 FROM public.organizations WHERE id=v_org AND owner_id=v_actor FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'DATA_RIGHTS_FORBIDDEN' USING ERRCODE='42501';END IF;
 IF private.admin_account_deletion_needs_review(v_actor,v_org)THEN
  RAISE EXCEPTION 'ACCOUNT_DELETION_REVIEW_REQUIRED' USING ERRCODE='55000';
 END IF;
 RETURN private.delete_account_pre_admin(p_confirmation_name,p_confirmation_phrase);
END $$;
REVOKE ALL ON FUNCTION public.delete_account_permanently(text,text) FROM PUBLIC,anon,service_role;
GRANT EXECUTE ON FUNCTION public.delete_account_permanently(text,text) TO authenticated;
COMMIT;
